def gen(rng):
    def fmt(ss, m, n):
        return f'{len(ss)} {m} {n}\n' + '\n'.join(ss)
    def rs(L, p1):
        return ''.join('1' if rng.random() < p1 else '0' for _ in range(L))
    tests = [fmt(['10', '0001', '111001', '1', '0'], 3, 5), fmt(['10', '0', '1'], 1, 1), fmt(['0', '1'], 0, 0),
             fmt(['0'], 0, 1), fmt(['1'], 0, 1), fmt(['1'], 1, 0), fmt(['11', '00', '01'], 2, 2), fmt(['1' * 100], 100, 100),
             fmt(['0' * 100, '1' * 100], 100, 100), fmt(['10'] * 10, 5, 5), fmt(['01', '10', '0011'], 3, 3)]
    for k in (2, 3, 4, 5, 6, 8, 10, 12):
        for _ in range(3):
            ss = [rs(rng.randint(1, 5), rng.random()) for _ in range(k)]
            tests.append(fmt(ss, rng.randint(0, 8), rng.randint(0, 8)))
    # max-size cases
    tests.append(fmt([rs(rng.randint(1, 100), 0.5) for _ in range(600)], 100, 100))
    tests.append(fmt([rs(rng.randint(1, 3), 0.5) for _ in range(600)], 100, 100))
    tests.append(fmt([rs(rng.randint(1, 20), rng.random()) for _ in range(600)], 100, 100))
    tests.append(fmt([rs(100, 0.5) for _ in range(600)], 100, 100))
    tests.append(fmt([rs(rng.randint(1, 6), 0.3) for _ in range(600)], 100, 100))
    tests.append(fmt([rs(rng.randint(1, 4), 0.5) for _ in range(600)], 100, 0))
    return tests
